import * as React from 'react';
import {
    AppBar,
    Container,
    IconButton,
    Tabs,
    Tab,
    Typography,
    Box,
    Button,
    List,
    ListItem,
    ListItemButton, ListItemText, Stack, Paper, Card, CardHeader, CardContent, CardMedia, CardActions, useTheme, Grid
} from "@mui/material";
import Divider from '@mui/material/Divider';
import {generatePath, Link, useNavigate} from "react-router";
import axios, {AxiosResponse} from "axios";
import {baseUrl, excursionsUrl, mainUrl, topicUrl} from "../../config/consts";
import {IPageResponse} from "../../common/response";
import {useEffect, useState} from "react";
import {Header} from "../../components/header/header-component";
import {ApplicationBar} from "../../components/appbar/application-bar";
import {baseRoute, excursionItemRoute, topicRouteUrl} from "../../config/routes";
import {Topic} from "../excursion-item-page/model";
import {Main} from "../../components/main-context/main";
import {StyledBadge} from "../../components/custom-badge/custom-badge.component";
import {ApplicationFooter} from "../../components/appbar/application-footer";

export interface ExcursionPageProps {

}


const TopicPage = (props: ExcursionPageProps) => {

    const navigate = useNavigate();

    const theme = useTheme();


    const [data, setData] = useState<IPageResponse<Topic>>({
        data: [],
        meta: {
            pagination: {
                page: 0,
                total: 0,
                pageCount: 0,
                pageSize: 0
            }
        }
    });

    useEffect(() => {
        axios.get(topicUrl, {
            params: {
                populate: ["cover", "places"],
            }
        }).then((response: AxiosResponse<IPageResponse<Topic>>) => {
            const data = response.data;
            axios.get(mainUrl).then((resp) => {
                const mainData: Main = resp.data as Main;
                const idxMap = new Map<number, number>();
                (mainData?.data?.attributes?.topics?.data || []).forEach((it, idx) => {
                    idxMap.set(it.id, idx + 1);
                })
                data.data.sort((t1, t2) => (idxMap.get(t1.id) || 0) - (idxMap.get(t2.id) || 0))
                setData(data)
            }).catch((reason) => {
                setData(data);
            })
        }).catch((error) => navigate(baseRoute));
    }, [])

    return <div>
        <div style={{position: "relative"}}>
            <div style={{
                opacity: 0.03,
                position: "absolute",
                height: "100%",
                width: "100%",
                backgroundImage: "url(https://sun1-16.userapi.com/impg/7MVdJ7k4B_ik2HbKWyM68zx4gtGqYCNN1kJjaQ/p1oqti9iNfs.jpg?size=1600x1068&quality=96&sign=7fc8494393646b3ff6e56456854acce9&type=album)"
            }}>

            </div>
            <ApplicationBar/>
            <Header title={"Достопримечательности"}/>
        </div>
        <Container>
            <Grid container spacing={4} sx={{
                [theme.breakpoints.down("md")]: {paddingTop: 4},
                [theme.breakpoints.down("sm")]: {paddingTop: 2},
                paddingBottom: 4,
                paddingTop: 8
            }}>
                {(data.data || []).map((it, idx) => <Grid size={{lg: 6, md: 6, xs: 12, sm: 12}} > <Paper style={{background: "unset", width:"100%",    height:"100%", display:"flex"}} key={idx}>

                    <Card sx={{
                        background: "unset",
                        cursor: 'pointer',
                        flex: 1,
                        display: {xs: "none", sm: "none", md: "none"}
                    }} onClick={() => navigate(generatePath(topicRouteUrl, {id: `${it.id}`}))}>
                        <CardMedia
                            component="img"
                            sx={{flex: 1, width: "40%"}}
                            image={baseUrl + (it.attributes?.cover?.data?.attributes?.formats?.medium?.url || '')}
                        />
                        <CardContent
                            sx={[{
                                display: "flex",
                                flexDirection: "column",
                                flex: 2,
                                width: "50%"
                            }]}>

                            <Typography variant={"h4"} textAlign={"center"} padding={4}>
                                <StyledBadge color={"primary"}
                                             badgeContent={it.attributes?.places?.data?.length}>
                                    {it.attributes?.caption || ''}
                                </StyledBadge>
                            </Typography>

                            <Divider/>
                            <Typography variant={"subtitle2"} textAlign={"left"} paddingTop={4} paddingBottom={4}>
                                {it.attributes?.description || ''}
                            </Typography>
                            <CardActions sx={{padding: 0}}
                                         onClick={() => navigate(generatePath(topicRouteUrl, {id: `${it.id}`}))}>
                                <Button>Показать</Button>
                            </CardActions>
                        </CardContent>
                    </Card>
                    <Card sx={{
                        display: "flex",
                        width: "100%",
                        flex: 1,
                        height:"100%",
                        cursor: "pointer",
                        flexDirection: "column"
                    }} onClick={() => navigate(generatePath(topicRouteUrl, {id: `${it.id}`}))}>
                        <CardContent
                            sx={[{
                                display: "block",
                                flexDirection: "column",
                                width: "100%"
                            }]}>
                            <Typography variant={"h4"} textAlign={"center"} padding={4}>
                                <StyledBadge color={"primary"}
                                             badgeContent={it.attributes?.places?.data?.length}>
                                    {it.attributes?.caption || ''}
                                </StyledBadge>
                            </Typography>
                        </CardContent>
                        <CardMedia
                            component="img"
                            sx={{width: "100%"}}
                            image={baseUrl + (it.attributes?.cover?.data?.attributes?.formats?.medium?.url || '')}
                        />
                        <CardContent
                            sx={[{
                                display: {sm: "block", md: "flex"},
                                flexDirection: "column",
                                width: "100%",
                                height: "100%"
                            }]}>

                            <Typography variant={"h6"} textAlign={"left"} paddingTop={4} paddingBottom={4}
                                        color={"textSecondary"} sx={{flex: 1}}>
                                {it.attributes?.description || ''}
                            </Typography>
                            <CardActions sx={{padding: 0}}>
                                <Button>Показать</Button>
                            </CardActions>
                        </CardContent>

                    </Card>
                </Paper>
                </Grid>)}
            </Grid>
        </Container>
        <ApplicationFooter/>
    </div>
}

export default TopicPage;