import { MainContext, MainContextData} from "../../components/main-context/main-context";
import {useEffect, useState} from "react";
import axios from "axios";
import {mainUrl} from "../../config/consts";
import {Main} from "../../components/main-context/main";

export const MainContextLoader = ({children}: any) => {

    const [mainData, setMainData] = useState<MainContextData | null>(null);

    useEffect(() => {
        axios.get(mainUrl).then((resp) => {
            const data: Main = resp.data as Main;
            const textMap = new Map<string, string>();
            (data?.data?.attributes?.texts || []).forEach(it=>{
                textMap.set(it.code, it.value);
            })
            const mainTopicId = Number(textMap.get("page.main.sections.section1.cards.groupid")) || -1;
            const mainTopicId2 = Number(textMap.get("page.main.sections.section2.cards.groupid")) || -1;
            setMainData({
                original: data,
                texts: textMap,
                mainTopicId: mainTopicId,
                mainTopicId2: mainTopicId2
            })
        })
    }, [])

    if (!mainData) {
        return null;
    }


    return <MainContext.Provider value={mainData}>
        {children || null}
    </MainContext.Provider>
}