import {ExcursionPageProps} from "../excursion-page/excursion-page.component";
import {generatePath, useLocation, useMatch, useMatches, useNavigate, useParams} from "react-router";
import {useEffect, useRef, useState} from "react";
import axios, {AxiosResponse} from "axios";
import {baseUrl, excursionItemUrl, excursionsUrl, sightsUrl} from "../../config/consts";
import {IResponse} from "../../common/response";
import {ApplicationBar} from "../../components/appbar/application-bar";
import {ReactComponent as Star} from "../../svg/star.svg";
import {
    Box,
    Button, capitalize,
    Card,
    CardActions,
    CardContent, CardHeader,
    CardMedia,
    Container, Grid,
    Paper,
    Stack,
    Typography,
    useTheme
} from "@mui/material";
import * as React from "react";
import {YandexMap} from "../../components/map/map.component";
import {ExcursionItem, Place} from "./model";
import {Qr} from "../../components/qrcode/qr-code.component";
import {baseRoute, excursionPlaceRoute, placeRoute} from "../../config/routes";
import {ReactComponent as Background} from "../../svg/background.svg";
import {generatePathApp} from "../../utils/genpath-util";
import {DirectionsBus, DirectionsWalk} from "@mui/icons-material";
import Time from "@mui/icons-material/esm/AccessTime";
import {ApplicationFooter} from "../../components/appbar/application-footer";

export interface ExcursionItemPageProps {

}

export const ExcursionItemPage = (props: ExcursionPageProps) => {
    const navigate = useNavigate();

    const location = useLocation();

    const id = useParams().id;

    const [data, setData] = useState<IResponse<ExcursionItem> | null>(null);

    const theme = useTheme();

    const cardsRef = useRef<Map<number, HTMLElement | null>>(new Map<number, HTMLElement>());

    useEffect(() => {
        if (!id) {
            setData(null);
            return;
        }
        axios.get(generatePathApp(excursionItemUrl, {id: id}), {
            params: {
                populate: "cover"
            }
        }).then((response: AxiosResponse<IResponse<ExcursionItem>>) => {
            const data = response.data;
            setData(data);
        }).catch((error) => navigate(baseRoute));
    }, [id])

    if (!data) {
        return null;
    }

    return <div>
        <div style={{position: "relative"}}>
            <div style={{
                opacity: 0.03,
                position: "absolute",
                height: "100%",
                width: "100%",
                backgroundImage: "url(https://sun1-16.userapi.com/impg/7MVdJ7k4B_ik2HbKWyM68zx4gtGqYCNN1kJjaQ/p1oqti9iNfs.jpg?size=1600x1068&quality=96&sign=7fc8494393646b3ff6e56456854acce9&type=album)"
            }}>
            </div>
            <ApplicationBar/>
        </div>

        <Stack spacing={4} sx={{
            [theme.breakpoints.down("md")]: {paddingTop: 4},
            [theme.breakpoints.down("sm")]: {paddingTop: 2},

            paddingTop: 12
        }}>
            <Paper style={{background: "unset"}} sx={{backgroundColor: "unset"}}>
                <Container>
                    <Stack flexDirection={"row-reverse"} alignItems={"center"}>
                        <Box sx={{[theme.breakpoints.down("lg")]: {display: "none"}}}>
                            <Qr url={window.location.href}/>
                        </Box>
                        <Stack spacing={4} sx={{
                            flex:1,
                            [theme.breakpoints.down("md")]: {paddingTop: 4},
                            [theme.breakpoints.down("sm")]: {paddingTop: 2},
                        }}>
                            <Typography variant={"h5"}>{data.data.attributes.caption || ''}</Typography>
                            <Typography variant={"subtitle1"}
                                        color={"textSecondary"}>{data.data.attributes.description}</Typography>
                            <Grid container rowSpacing={2}>
                                {(data.data.attributes.type || '') &&
                                    <Grid size={{lg: 4, md: 12, sm: 12, xs: 12}} container spacing={1}
                                          alignItems="center"
                                          flexWrap={"nowrap"}>
                                        <Grid>
                                            <Typography variant="subtitle1" color={"textSecondary"}>
                                                {capitalize(data.data.attributes.type || '')} экскурсия
                                            </Typography>
                                        </Grid>
                                    </Grid>
                                }
                                {(data.data.attributes.distance || '') &&
                                    <Grid size={{lg: 4, md: 12, sm: 12, xs: 12}} container spacing={1}
                                          alignItems="center"
                                          flexWrap={"nowrap"}>
                                        <Grid>
                                            <Typography variant={"subtitle1"} color={"textSecondary"}>
                                                Дистанция:
                                            </Typography>
                                        </Grid>
                                        <Grid>
                                            <Typography variant="subtitle1" color={"textSecondary"}>
                                                {data.data.attributes.distance || ''}
                                            </Typography>
                                        </Grid>
                                    </Grid>
                                }
                            </Grid>
                        </Stack>
                    </Stack>

                </Container>
            </Paper>
            {(data?.data?.attributes?.centerLat && data?.data?.attributes?.centerLon) ?
                <Paper sx={{paddingTop: 4, paddingBottom: 4, position: "relative",   [theme.breakpoints.down("sm")]: {padding: 0},}}>
                    <Box sx={{position: "absolute", top: 0, zIndex: 0, right: 0, bottom: 0, left: 0}}>
                        <Background style={{width: "100%", height: "100%"}}/>
                    </Box>
                    <Container sx={{
                        [theme.breakpoints.down("sm")]: {padding: 0},
                    }}>
                        <Stack spacing={4} sx={{
                            [theme.breakpoints.down("md")]: {paddingTop: 4},
                            [theme.breakpoints.down("sm")]: {padding: 0},
                        }}>
                            <YandexMap
                                center={{
                                    lat: Number(data.data.attributes.centerLat),
                                    lon: Number(data.data.attributes.centerLon)
                                }}
                                disableControls={true}
                                places={data.data?.attributes?.places?.data || []}
                                onPlaceClick={(place: Place) => {
                                    if (place) {
                                        navigate(generatePath(excursionPlaceRoute, {
                                            id: `${place.id || ''}`,
                                            eId: `${id || ''}`
                                        }))
                                    }
                                }}
                                style={{
                                    height: 400,
                                }}
                                zoom={data.data.attributes.zoom || 14}
                                route={(data?.data?.attributes?.geoJSON?.features && data?.data?.attributes?.geoJSON?.features[0].geometry?.coordinates || []).map(it => [it[1], it[0]])}
                                isExcursion={true}
                            />
                        </Stack>
                    </Container>
                </Paper>
                : null}
            {!(data?.data?.attributes.places.data) ? null :
                <Paper style={{background: "unset"}} sx={{backgroundColor: "unset"}}>
                    <Container sx={{
                        [theme.breakpoints.down("sm")]: {padding: 0},
                    }}>
                        <Stack spacing={4} paddingTop={4} paddingBottom={4} sx={{
                            [theme.breakpoints.down("md")]: {paddingTop: 4},
                            [theme.breakpoints.down("sm")]: {paddingTop: 2},
                        }}>
                            <Typography variant={"h5"}>Маршрут</Typography>
                        </Stack>
                        <Grid container rowSpacing={4} columnSpacing={4} paddingTop={4} paddingBottom={4}
                              flexDirection={"row"} flexWrap={"wrap"}>
                            {(data?.data?.attributes.places.data || []).map(it =>
                                <Grid size={{md: 4, sm: 6, xs: 12}}>
                                    <Card ref={(el) => {
                                        el && it.id ? cardsRef.current.set(it.id, el) : cardsRef.current.delete(it.id)
                                    }} sx={{cursor:"pointer", height: "100%", position: "relative", paddingBottom: 6, [theme.breakpoints.down("sm")]: {background: "none"}}}
                                          onClick={() => navigate(generatePath(excursionPlaceRoute, {
                                              id: `${it.id || ''}`,
                                              eId: `${id || ''}`
                                          }))}>
                                        <CardMedia
                                            src={it.attributes.pictures[0].image?.data?.attributes?.formats?.small?.url && `${baseUrl}/${it.attributes.pictures[0].image?.data?.attributes?.formats?.small?.url}` || ''}
                                            sx={{aspectRatio: "37 / 22"}}
                                            component="img"/>
                                        <CardContent>
                                            <Stack spacing={2} paddingTop={2}>
                                                <Typography variant={"h6"}>{it.attributes.caption || ''}</Typography>
                                                <Typography
                                                    variant={"subtitle1"}
                                                    color={"textSecondary"}>{it.attributes.description || ''}</Typography>
                                            </Stack>
                                        </CardContent>
                                        <CardActions sx={{bottom: 0, position: "absolute"}}>
                                            <Button onClick={() => navigate(generatePath(excursionPlaceRoute, {
                                                id: `${it.id || ''}`,
                                                eId: `${id || ''}`
                                            }))}>Показать</Button>
                                        </CardActions>
                                        <Box sx={{position: "absolute", right: "0", bottom: "0", zIndex: 1}}>
                                            <Star/>
                                        </Box>
                                    </Card>
                                </Grid>)
                            }
                        </Grid>
                    </Container>
                </Paper>}
        </Stack>
        <ApplicationFooter/>
    </div>
}